CREATE POLICY "Users read own notebook covers" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'notebook-covers' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users upload own notebook covers" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'notebook-covers' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users update own notebook covers" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'notebook-covers' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users delete own notebook covers" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'notebook-covers' AND auth.uid()::text = (storage.foldername(name))[1]);